#[test]
fn periodic_noise_matches_js_bit_for_bit() {
    for c in CASES {
        let a = pvnoise(c.x, c.y, c.s, c.p_x);
        assert_eq!(a, c.vnoise, "pvnoise({}, {}, {}, {}): got {a}, expected {}", c.x, c.y, c.s, c.p_x, c.vnoise);
        let b = pfbm(c.x, c.y, c.s, c.p_x);
        assert_eq!(b, c.fbm, "pfbm({}, {}, {}, {}): got {b}, expected {}", c.x, c.y, c.s, c.p_x, c.fbm);
        let d = pridged(c.x, c.y, c.s, c.p_x);
        assert_eq!(d, c.ridged, "pridged({}, {}, {}, {}): got {d}, expected {}", c.x, c.y, c.s, c.p_x, c.ridged);
    }
}
